# ================= 5G DEFAULT TEMPLATE DOWNLOAD =================
def download_5g_default_files():
    import base64
    st.subheader('📥 Download Saved Default Files')
    st.caption('5G module default templates')

    files = {
        'Sample 5G MRF(7).xlsx': '',
        'Sample_5G_ Only GPS(4).xlsx': '',
        'Solution file(7).xlsx': '',
    }

    for name, data in files.items():
        st.download_button(
            label=f'Download {name}',
            data=base64.b64decode(data),
            file_name=name,
            mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            key='5g_default_'+name
        )

def show_5g_module():
    import zipfile
    import tempfile
    from openpyxl import load_workbook

    st.title('📡 5G MRF Automation')

    # Saved default templates only for 5G module
    download_5g_default_files()

    template_upload = st.file_uploader('1. Upload Sample 5G MRF.xlsx', type=['xlsx'], key='5g_template')
    solution_upload = st.file_uploader('2. Upload Solution File.xlsx', type=['xlsx'], key='5g_solution')

    if st.button('Generate 5G MRF', key='generate_5g'):
        if not template_upload or not solution_upload:
            st.error('Please upload both files.')
            return

        out=[]
        folder=tempfile.mkdtemp()
        solution_wb=load_workbook(solution_upload)
        ws=solution_wb.active

        for row in range(2, ws.max_row+1):
            site=ws[f'A{row}'].value
            if not site:
                continue
            wb=load_workbook(template_upload)
            sh=wb.active
            sh['G10']=site
            sh['G9']=ws[f'B{row}'].value or ''
            sh['G11']=ws[f'C{row}'].value or ''
            sh['J9']=ws[f'D{row}'].value or ''
            sh['J11']=ws[f'D{row}'].value or ''

            name=str(site).replace('/','_')
            material=str(ws[f'C{row}'].value or '').replace('/','_')
            path=os.path.join(folder,f'{name}_MRF_{material}.xlsx')
            wb.save(path)
            out.append(path)

        st.success(f'{len(out)} MRF file generated')

        zip_path=os.path.join(folder,'5G_MRF_All_Files.zip')
        with zipfile.ZipFile(zip_path,'w') as z:
            for f in out:
                z.write(f,os.path.basename(f))

        with open(zip_path,'rb') as f:
            st.download_button('Download All 5G MRF ZIP',f,file_name='5G_MRF_All_Files.zip')

        for f in out:
            with open(f,'rb') as x:
                st.download_button('Download '+os.path.basename(f),x,file_name=os.path.basename(f),key=f)

    st.divider()
    st.subheader('3. MRF Edit')
    edit=st.file_uploader('Upload Generated MRF for Edit',type=['xlsx'],key='5g_edit')
    if edit:
        st.download_button('Download Edited MRF',edit,file_name='Edited_'+edit.name)





