def show_others_module():
    # ============================================================
    # UPLOAD MRF + COMBINED ALL MRF (OTHERS MODULE)
    # Existing CC_MOD and previous 5G logic remain unchanged.
    # ============================================================

    st.title('📦 Others - MRF Combine')
    st.write('Upload multiple MRF Excel files and create one combined MRF workbook.')

    combine_tab1, combine_tab2 = st.tabs([
        'Upload MRF',
        'Combined All MRF'
    ])

    with combine_tab1:
        combine_uploads = st.file_uploader(
            'Upload Multiple 5G MRF Excel Files',
            type=['xlsx', 'xls'],
            accept_multiple_files=True,
            key='others_combine_uploads'
        )

        st.caption('Upload all MRF Excel files here. The original combine + Site Name logic will be applied.')

        if st.button('Combine Uploaded MRF Files', key='others_combine_button', use_container_width=True):
            if not combine_uploads:
                st.error('Please upload at least one MRF Excel file.')
            else:
                try:
                    all_dfs = []

                    for uploaded in combine_uploads:
                        uploaded.seek(0)

                        # Keep the original combine-script behavior first.
                        # If the workbook has title rows before the real header,
                        # automatically detect the row containing Material Description.
                        try:
                            temp_df = pd.read_excel(uploaded, engine='openpyxl')
                            temp_df.columns = temp_df.columns.astype(str).str.strip()
                        except Exception:
                            uploaded.seek(0)
                            temp_df = pd.read_excel(uploaded)
                            temp_df.columns = temp_df.columns.astype(str).str.strip()

                        if 'Material Description' not in temp_df.columns:
                            uploaded.seek(0)
                            raw = pd.read_excel(uploaded, header=None, engine='openpyxl')
                            header_row = None

                            for i, row in raw.iterrows():
                                row_text = ' '.join('' if pd.isna(v) else str(v) for v in row.tolist()).lower()
                                if 'material' in row_text and 'description' in row_text:
                                    header_row = i
                                    break

                            if header_row is not None:
                                uploaded.seek(0)
                                temp_df = pd.read_excel(uploaded, header=header_row, engine='openpyxl')
                                temp_df.columns = temp_df.columns.astype(str).str.strip()

                        temp_df['__Source_File'] = uploaded.name
                        all_dfs.append(temp_df)

                    combined_df = pd.concat(all_dfs, ignore_index=True, sort=False)
                    combined_df.columns = combined_df.columns.astype(str).str.strip()

                    # ---------------- Original Site Name logic ----------------
                    if 'Material Description' not in combined_df.columns:
                        raise KeyError(
                            'Material Description column not found. Available columns: ' +
                            ', '.join(combined_df.columns.astype(str))
                        )

                    def _extract_site_code_others(text):
                        if isinstance(text, str):
                            candidates = re.findall(r'\b[A-Z0-9]{7}\b', text)
                            for code in candidates:
                                first5 = code[:5]
                                last2 = code[5:]
                                if not re.fullmatch(r'[A-Z]{5}', first5):
                                    continue
                                if not re.fullmatch(r'[A-Z0-9]{2}', last2):
                                    continue
                                return code
                        return None

                    combined_df['Site Name'] = combined_df['Material Description'].apply(_extract_site_code_others)
                    combined_df['Site Name'] = combined_df['Site Name'].ffill()

                    columns_needed = [
                        'Material code',
                        'Plant',
                        'Storage Location',
                        'Name of Storage',
                        'Material Description',
                        'Quantity',
                        'AA',
                        'AB',
                        'AC'
                    ]

                    existing_columns = [col for col in columns_needed if col in combined_df.columns]
                    subset = combined_df[existing_columns].copy()
                    subset['Site Name'] = combined_df['Site Name']

                    if 'Material code' not in subset.columns:
                        raise KeyError('Material code column not found in uploaded MRF files.')

                    if 'Quantity' not in subset.columns:
                        raise KeyError('Quantity column not found in uploaded MRF files.')

                    subset = subset.dropna(subset=['Material code'])
                    subset['Material code'] = subset['Material code'].astype(str)
                    subset['Quantity'] = pd.to_numeric(subset['Quantity'], errors='coerce').fillna(0)

                    # Original script logic: Name is taken from Excel column position 12 when available.
                    subset['Name'] = combined_df.iloc[:, 11] if combined_df.shape[1] >= 12 else ''

                    ordered_cols = [
                        'Material code',
                        'Plant',
                        'Storage Location',
                        'Name of Storage',
                        'Material Description',
                        'Quantity',
                        'Site Name',
                        'Name',
                        'AA',
                        'AB',
                        'AC'
                    ]
                    subset = subset[[col for col in ordered_cols if col in subset.columns]]

                    summary = subset.groupby(
                        'Material code',
                        as_index=False
                    ).agg({
                        'Material Description': 'first',
                        'Quantity': 'sum'
                    })

                    summary = summary[summary['Quantity'] != 0]

                    def _description_match_others(desc):
                        if not isinstance(desc, str):
                            return ''
                        desc_lower = desc.lower()
                        if '4 3-10' in desc_lower:
                            return '4 3-10 Found'
                        elif '7by16' in desc_lower or '7 by 16' in desc_lower:
                            return '7by16 Found'
                        return ''

                    summary.insert(
                        1,
                        'Description Match',
                        summary['Material Description'].apply(_description_match_others)
                    )
                    summary = summary.sort_values('Material code')

                    description_summary = subset.groupby(
                        'Material Description',
                        as_index=False
                    ).agg({'Quantity': 'sum'})
                    description_summary = description_summary.sort_values('Quantity', ascending=False)

                    keywords = ['B1', 'B3', 'B8']
                    mc_rows = []

                    for _, row in summary.iterrows():
                        description = str(row['Material Description']).upper()
                        for key in keywords:
                            if key in description:
                                mc_rows.append({
                                    'Material code': row['Material code'],
                                    'Match': key,
                                    'Quantity': row['Quantity']
                                })
                                break

                    mc_info_df = pd.DataFrame(mc_rows)

                    x_cols = [col for col in ['AA', 'AB', 'AC'] if col in subset.columns]

                    if x_cols:
                        x_count_df = subset.copy()
                        x_count_df['X Count'] = x_count_df[x_cols].apply(
                            lambda x: sum(x == 'X'),
                            axis=1
                        )
                    else:
                        x_count_df = subset.copy()
                        x_count_df['X Count'] = 0

                    x_count_df = x_count_df[x_count_df['Quantity'] != 0]

                    output_buffer = io.BytesIO()
                    with pd.ExcelWriter(output_buffer, engine='openpyxl') as writer:
                        subset.to_excel(writer, sheet_name='Filtered_Data', index=False)
                        summary.to_excel(writer, sheet_name='Summary', index=False)
                        description_summary.to_excel(writer, sheet_name='Description_Summary', index=False)
                        mc_info_df.to_excel(writer, sheet_name='MC info', index=False)
                        x_count_df.to_excel(writer, sheet_name='X_Count', index=False)

                    output_buffer.seek(0)

                    st.session_state['others_combined_excel'] = output_buffer.getvalue()
                    st.session_state['others_combined_preview'] = subset
                    st.session_state['others_combined_file_count'] = len(combine_uploads)

                    st.success(f'Successfully combined {len(combine_uploads)} MRF files.')

                except Exception as e:
                    st.error('Failed to combine uploaded MRF files.')
                    st.exception(e)

    with combine_tab2:
        if 'others_combined_excel' in st.session_state:
            st.success(
                f"Combined All MRF is ready. Files combined: {st.session_state.get('others_combined_file_count', 0)}"
            )

            preview_df = st.session_state.get('others_combined_preview')
            if preview_df is not None:
                st.dataframe(preview_df, use_container_width=True, height=420)

            st.download_button(
                label='Download Combined All MRF',
                data=st.session_state['others_combined_excel'],
                file_name='Combined_All_MRF.xlsx',
                mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                key='download_others_combined_all',
                use_container_width=True
            )
        else:
            st.info('Go to Upload MRF tab, upload multiple MRF Excel files, and click Combine Uploaded MRF Files.')




