def show_new_bts_module():
    import zipfile
    import tempfile
    from openpyxl import load_workbook

    st.title("📡 New BTS MRF Automation")

    download_new_bts_default_files()

    template_upload = st.file_uploader(
        "1. Upload Sample New BTS MRF Template",
        type=["xlsx", "xlsb"],
        key="new_bts_template"
    )

    solution_upload = st.file_uploader(
        "2. Upload Solution File.xlsx",
        type=["xlsx"],
        key="new_bts_solution"
    )

    if st.button("Generate New BTS MRF", key="generate_new_bts"):

        if not template_upload or not solution_upload:
            st.error("Please upload both files.")
            return

        try:
            out=[]
            folder=tempfile.mkdtemp()

            solution_wb=load_workbook(solution_upload)
            ws=solution_wb.active

            for row in range(2, ws.max_row+1):
                site=ws[f"A{row}"].value
                if not site:
                    continue

                wb=load_workbook(template_upload)
                sh=wb.active

                sh["G10"]=site
                sh["G9"]=ws[f"B{row}"].value or ""
                sh["G11"]=ws[f"C{row}"].value or ""
                sh["J9"]=ws[f"D{row}"].value or ""
                sh["J11"]=ws[f"D{row}"].value or ""

                name=str(site).replace("/","_")
                path=os.path.join(
                    folder,
                    f"{name}_MRF_New_BTS.xlsx"
                )

                wb.save(path)
                out.append(path)

            st.success(f"{len(out)} New BTS MRF file generated")

            zip_path=os.path.join(
                folder,
                "New_BTS_MRF_All_Files.zip"
            )

            with zipfile.ZipFile(zip_path,"w") as z:
                for f in out:
                    z.write(f, os.path.basename(f))

            with open(zip_path,"rb") as f:
                st.download_button(
                    "Download All New BTS MRF ZIP",
                    f,
                    file_name="New_BTS_MRF_All_Files.zip"
                )

            for f in out:
                with open(f,"rb") as x:
                    st.download_button(
                        "Download "+os.path.basename(f),
                        x,
                        file_name=os.path.basename(f),
                        key="new_bts_"+os.path.basename(f)
                    )

        except Exception as e:
            st.exception(e)



